harness.enable:
const results = await axe.run({
  rules: { 'audio-caption': { enabled: true }, 'video-caption': { enabled: true } },
  runOnly: { type: 'rule', values: Object.keys(m.axeHandlers) }
});
for (const item of [...(results.violations || []), ...(results.incomplete || [])]) {
  const handler = m.axeHandlers[item.id];
  if (!handler) continue;
  for (const node of item.nodes || []) {
    try {
      const selector = Array.isArray(node.target) ? node.target.join(' ') : node.target;
      const el = document.querySelector(selector);
      if (el) await handler(el);
    } catch (e) {
      console.error('Handler error:', e);
    }
  }
}
